  .supply(linear.issues({ apiKey: trackerKey, team: 'ENG', labels: ['bug'] }), (issue, to) =>
    to.create({ ref: issue.identifier, title: issue.title, body: issue.description }))
  .supply(folder.files({ path: 'bugs', glob: '*.md' }), (file, to) =>
