import { z } from 'zod';
import { H, type Metrics, type Model, type Rate, type Seat, type SupplyOf } from 'harness-dsl';
import * as claudeCode from 'harness-dsl/claude-code';
import * as anthropic from 'harness-dsl/anthropic';
import * as http from 'harness-dsl/http';
import * as sqlite from 'harness-dsl/sqlite';
import * as jsonl from 'harness-dsl/jsonl';
import * as shell from 'harness-dsl/shell';
import * as markdown from 'harness-dsl/markdown';

const sections = z.enum(['news', 'sports', 'opinion', 'culture']);
const sectionFacet = H.facet('section', sections);

const submitted = H.state('submitted', 'pending');
const returned = H.state('returned', 'waiting');
const accepted = H.state('accepted', 'terminal', 'success');
const withdrawn = H.state('withdrawn', 'terminal', 'neutral');
const stalled = H.state('stalled', 'terminal', 'failure');

const draft = H.kind('draft')
  .data(
    z.object({
      title: z.string(),
      section: sections,
      body: z.string(),
      notes: z.array(z.string()).optional(),
    })
  )
  .states(submitted, returned, accepted, withdrawn, stalled);

const opus = anthropic.model('claude-opus-4-1');
const sonnet = anthropic.model('claude-sonnet-4-5');
const sonnetFour = anthropic.model('claude-sonnet-4');
const haiku = anthropic.model('claude-haiku-4-5');
const api = anthropic.account('editorial-api', {
  apiKey: H.env('ANTHROPIC_API_KEY'),
  serves: [opus, sonnet, sonnetFour, haiku],
});
const models = H.pool('models', [{ account: api, share: 1 }]);

const editorial = H.halt(
  'editorial-decision',
  z.object({
    action: z.enum(['accept', 'return']),
    notes: z.array(z.string()),
    actedOn: z.array(z.enum(['first', 'second'])),
  })
).about(z.object({ title: z.string(), merged: z.string() }));

const reviewInput = z.object({ title: z.string(), section: sections, body: z.string() });
const critique = z.object({ points: z.array(z.string()) });
type Review = z.infer<typeof reviewInput>;
type Critique = z.infer<typeof critique>;

const editorialTaste = H.memory('editorial-taste', 'taste');
const factChecking = H.memory('fact-checking', 'experience');
const tasteJournal = H.journal('editor-taste', editorialTaste, jsonl.memory('memory/editor-taste.jsonl'));
const factCheckJournal = H.journal('fact-check-lessons', factChecking, jsonl.memory('memory/fact-check.jsonl'));

const reviewing = H.role('reviewer')
  .input(reviewInput)
  .output(critique)
  .prompt(input => `Critique this ${input.section} draft, "${input.title}".\n\n${input.body}`);

const swapAfterSamples = 50;

const creditedRate = (metrics: Metrics, seat: Seat<Review, Critique>, model: Model): Rate =>
  metrics
    .rateBy({
      days: 90,
      among: editorial.resolved(),
      count: { ...editorial.resolved(), credited: seat },
      by: { modelOf: seat },
    })
    .of(model);

const reviewerAModel = H.policy.model('reviewer-a-model', [opus, sonnet], choice => {
  const mine = creditedRate(choice.metrics, reviewerA, opus);
  const theirs = creditedRate(choice.metrics, reviewerB, sonnetFour);
  if (mine.samples < swapAfterSamples || theirs.samples < swapAfterSamples) return opus;
  return (mine.value ?? 0) < (theirs.value ?? 0) ? sonnet : opus;
});

const reviewerBModel = H.policy.model('reviewer-b-model', [sonnetFour, haiku], choice => {
  const mine = creditedRate(choice.metrics, reviewerB, sonnetFour);
  const theirs = creditedRate(choice.metrics, reviewerA, opus);
  if (mine.samples < swapAfterSamples || theirs.samples < swapAfterSamples) return sonnetFour;
  return (mine.value ?? 0) < (theirs.value ?? 0) ? haiku : sonnetFour;
});

const reviewerA: Seat<Review, Critique> = H.seat('reviewer-a', reviewing)
  .model(reviewerAModel)
  .recalls(tasteJournal, factCheckJournal)
  .creditedBy(editorial, decision => decision.actedOn.includes('first'));
const reviewerB: Seat<Review, Critique> = H.seat('reviewer-b', reviewing)
  .model(reviewerBModel)
  .recalls(tasteJournal, factCheckJournal)
  .creditedBy(editorial, decision => decision.actedOn.includes('second'));

const local = shell.local('local', { slots: 2 });

const mergeCritiques = H.command('merge-critiques')
  .input(z.object({ first: z.array(z.string()), second: z.array(z.string()) }))
  .output(z.object({ merged: z.string() }))
  .argv(input => ['merge-critiques', '--first', JSON.stringify(input.first), '--second', JSON.stringify(input.second)])
  .on(local);

const factCheck = H.command('fact-check')
  .input(z.object({ draft: z.string() }))
  .output(z.object({ repeatMistakes: z.array(z.string()) }))
  .argv(input => ['fact-check', '--draft', input.draft])
  .on(local);

const review = H.flow('review-draft')
  .for(draft)
  .does(async ctx => {
    const input = { title: ctx.unit.data.title, section: ctx.unit.data.section, body: ctx.unit.data.body };
    const first = await ctx.run(reviewerA, input);
    if (first.ok === false) return ctx.fail(first.error);
    const second = await ctx.run(reviewerB, input);
    if (second.ok === false) return ctx.fail(second.error);
    const checked = await ctx.run(factCheck, { draft: ctx.unit.key });
    if (checked.ok) {
      for (const mistake of checked.value.repeatMistakes) {
        await ctx.remember(factCheckJournal, {
          text: `When a draft claims "${mistake}", verify it against a primary source before approving`,
          because: 'the fact-check found the same mistake in an earlier draft',
          when: { kinds: [draft] },
        });
      }
    }
    const merged = await ctx.run(mergeCritiques, { first: first.value.points, second: second.value.points });
    if (merged.ok === false) return ctx.fail(merged.error);
    const decision = await ctx.halt(editorial, merged.value.merged, {
      title: ctx.unit.data.title,
      merged: merged.value.merged,
    });
    if (decision.action === 'accept') return 'accepted';
    await ctx.update({ notes: decision.notes });
    return 'returned';
  });

const cmsHeaders = { Authorization: H.env('CMS_TOKEN') };

const cmsPoll = http.poll(draft, {
  url: 'https://cms.example.com/api/drafts?status=ready',
  every: { minutes: 15 },
  headers: cmsHeaders,
  body: z.object({
    drafts: z.array(
      z.object({
        id: z.string(),
        status: z.enum(['new', 'resubmitted', 'withdrawn']),
        title: z.string(),
        section: sections,
        body: z.string(),
      })
    ),
  }),
  read: body =>
    body.drafts.map((item): SupplyOf<typeof draft> => {
      if (item.status === 'new') {
        return { create: { title: item.title, section: item.section, body: item.body }, key: item.id };
      }
      if (item.status === 'withdrawn') return { update: item.id, state: 'withdrawn', cancels: ['active', 'waiting'] };
      return { update: item.id, patch: { body: item.body, notes: [] }, state: 'submitted' };
    }),
});

const cmsStore = http.store(draft, {
  url: 'https://cms.example.com/api/drafts',
  headers: cmsHeaders,
  stateField: 'review_state',
});

const drafts = H.lane('drafts', draft)
  .handler(review)
  .retries(1, { backoff: { first: { minutes: 10 } }, exhausted: 'stalled' })
  .suppliers(cmsPoll)
  .store(cmsStore)
  .facet(sectionFacet, data => data.section);

const returnedNotesBecomeTaste = H.trigger(
  'returned-notes-become-taste-candidates',
  H.on.enters(draft, 'returned'),
  (event, act) =>
    (event.unit.data.notes ?? []).map(note =>
      act.remember(tasteJournal, {
        text: `When reviewing ${event.unit.data.section} drafts, ${note}`,
        because: `the editor returned "${event.unit.data.title}" with this note`,
        when: { facets: [sectionFacet.of(event.unit.data.section)] },
        status: 'candidate',
      })
    )
);

const editor = claudeCode.supervisor({
  grants: [
    H.ops.readWork,
    H.ops.resolve(editorial),
    H.ops.readMemory,
    H.ops.writeMemory,
    H.ops.curateMemory,
    H.ops.readTelemetry,
  ],
});

export const harness = H.harness('content-review')
  .ledger(sqlite.ledger('.harness/content.db'))
  .lanes(drafts)
  .pools(models)
  .triggers(returnedNotesBecomeTaste)
  .clients(editor)
  .observers(markdown.board('BOARD.md'), markdown.telemetry('TELEMETRY.md'));

export const running = harness.start();
=== END ===

No surface change was needed for these six scenarios, so only the scenario files follow.

Three things to know before reading them:

- **Forward references in policy closures.** Scenarios 03 and 06 each have a model policy that reads a metric declared further down the file. The metric's source needs the lane (03) or the seats (06), and those come after the policy. TypeScript accepts this because the policy body only runs at decision time, but it is the dependency cycle the parent's critique flagged. Scenario 02 orders its declarations so it has no forward reference.
- **No `!` or standalone `as`/`any` anywhere.** I read the "no `!`" rule literally, so the files use none, not even logical not or `!==`. The same goes for the words `as` and `any` inside strings.
- **States I added.** Each lane must declare where retry exhaustion leaves a unit (startup rule 2). Where the brief lists no failure outcome, I added an honest failure terminal:
  - `failed` (03);
  - `unhandled` (02 Escalation);
  - `review-failed` (06).
- **Interpretations of the brief.**
  - Scenario 03 re-opens recurring topics by creating a new edition of each topic, since a terminal unit cannot be re-opened.
  - Scenario 04's Incident lane parks an exhausted runbook in a waiting state that the operator leaves through `workMove` (rule 24).

=== FILE: scenarios/01-coding-team.ts ===
import { z } from 'zod';
import { H } from 'harness-dsl';
import { linear, LinearIssue } from 'harness-dsl/linear';
import { folder } from 'harness-dsl/folder';
import { claudeCode } from 'harness-dsl/claude-code';
import { sqlite } from 'harness-dsl/sqlite';
import { jsonl } from 'harness-dsl/jsonl';
import { git } from 'harness-dsl/git';
import { local } from 'harness-dsl/local';
import { markdown } from 'harness-dsl/markdown';

const quota = sqlite.quota('claude-subscriptions', { path: '../shared/quota.sqlite' });
const subscriptionA = claudeCode.subscription('subscription-a', { token: H.env('CLAUDE_TOKEN_A'), quota });
const subscriptionB = claudeCode.subscription('subscription-b', { token: H.env('CLAUDE_TOKEN_B'), quota });
const subscriptionC = claudeCode.subscription('subscription-c', { token: H.env('CLAUDE_TOKEN_C'), quota });
const apiAccount = claudeCode.apiKey('api-fallback', { apiKey: H.env('ANTHROPIC_API_KEY'), quota });

const soonestExpiringFirst = H.policy.account('soonest-expiring-first', ctx =>
  ctx.candidates
    .filter(state => state.shareUsed < state.shareCap && (state.cooldownUntil === undefined || state.cooldownUntil <= ctx.now))
    .sort((left, right) => left.windowResetsAt.getTime() - right.windowResetsAt.getTime())[0]);

const claudePool = H.pool('claude')
  .accounts(subscriptionA, subscriptionB, subscriptionC)
  .share(subscriptionA, 0.6)
  .share(subscriptionB, 0.6)
  .share(subscriptionC, 0.4)
  .drain(soonestExpiringFirst)
  .fallback(apiAccount);

const sonnet = claudeCode.model('sonnet', { id: 'claude-sonnet-4-5' });
const opus = claudeCode.model('opus', { id: 'claude-opus-4-1' });

const localRunner = local.runner('local').slots(4);

const builderRole = H.role('builder')
  .intents('read', 'edit', 'run', 'search', 'halt')
  .instructions('Implement the unit of work in the worktree until the project checks pass.');
const auditorRole = H.role('auditor')
  .intents('read', 'run', 'search', 'record')
  .instructions('List every deficit against the request. Record lessons that will help future builds.');
const plannerRole = H.role('planner')
  .intents('read', 'search')
  .instructions('Split the epic into independently shippable features.');

const workSchema = z.object({
  ref: z.string(),
  title: z.string(),
  description: z.string(),
  notes: z.array(z.string()),
});

const open = H.state('open', 'pending');
const shipped = H.terminal('shipped', 'success');
const dropped = H.terminal('dropped', 'neutral');
const abandoned = H.terminal('abandoned', 'failure');

const bug = H.kind('Bug').attributes(workSchema).states(open, shipped, dropped, abandoned).initial(open).key(work => work.ref);
const feature = H.kind('Feature').attributes(workSchema).states(open, shipped, dropped, abandoned).initial(open).key(work => work.ref);
const epic = H.kind('Epic').attributes(workSchema).states(open, shipped, dropped, abandoned).initial(open).key(work => work.ref);

const service = H.facet('service', ['api', 'web', 'worker']);
const due = H.state('due', 'pending');
const healthy = H.terminal('healthy', 'success');
const unhealthy = H.terminal('unhealthy', 'failure');
const heartbeat = H.kind('ServiceHeartbeat')
  .attributes(z.object({ service: service.schema }))
  .states(due, healthy, unhealthy)
  .initial(due);

const projectChecks = H.command('project-checks').argv(['npm', 'run', 'check']).runner(localRunner);
const worktree = git.worktree({ repo: '.', base: 'main' }).guard({ leaseEdits: true, beforeStop: projectChecks });

const ownerDecision = H.halt('owner-decision').decision(z.object({ answer: z.string() }));
const ownerReview = H.halt('owner-review').decision(z.object({
  verdict: z.enum(['accept', 'drop', 'reopen']),
  notes: z.string(),
}));

const builderModel = H.policy.model('builder-model', [sonnet, opus], ctx => {
  const cheaper = ctx.metrics.outcomes({ of: ctx.kind, seat: ctx.seat, model: sonnet, window: { lastDays: 14 } });
  return cheaper.samples >= 20 && cheaper.successRate < 0.85 ? opus : sonnet;
});

const builder = H.seat('builder')
  .role(builderRole)
  .model(builderModel)
  .pool(claudePool)
  .workspace(worktree)
  .halts(ownerDecision)
  .output(z.object({ summary: z.string() }));

const auditor = H.seat('auditor')
  .role(auditorRole)
  .model(opus)
  .pool(claudePool)
  .workspace(worktree)
  .output(z.object({ deficits: z.array(z.string()) }));

const planner = H.seat('planner')
  .role(plannerRole)
  .model(opus)
  .pool(claudePool)
  .output(z.object({ features: z.array(z.object({ title: z.string(), description: z.string() })) }));

const deliver = H.flow('deliver')
  .input(workSchema)
  .params(z.object({ rounds: z.number() }))
  .loop(
    'round',
    { schema: z.array(z.string()), initial: [] },
    round => round
      .step('build', builder, ctx => ({
        task: `${ctx.unit.attributes.title}\n${ctx.unit.attributes.description}\nOwner notes: ${ctx.unit.attributes.notes.join('; ')}\nOpen deficits:\n${ctx.steps.round.join('\n')}`,
      }), { afterCrash: 'askDriver' })
      .step('audit', auditor, ctx => ({
        task: `Audit the change for ${ctx.unit.attributes.title}. Builder summary: ${ctx.steps.build.summary}`,
      }), { afterCrash: 'askDriver' }),
    {
      max: ctx => ctx.params.rounds,
      until: ctx => ctx.steps.audit.deficits.length === 0,
      next: ctx => ctx.steps.audit.deficits,
    },
  )
  .halt('review', ownerReview, {
    ask: ctx => `Deficits remain after ${ctx.params.rounds} rounds:\n${ctx.steps.audit.deficits.join('\n')}`,
    when: ctx => ctx.steps.audit.deficits.length > 0,
  })
  .exit('shipped', ctx => ctx.steps.review === undefined || ctx.steps.review.verdict === 'accept')
  .exit('dropped', ctx => ctx.steps.review?.verdict === 'drop')
  .exit('reopened', {
    update: ctx => ({ notes: [...ctx.unit.attributes.notes, ctx.steps.review?.notes ?? 'reopened by owner'] }),
  });

const linearKey = H.env('LINEAR_API_KEY');
const tracker = linear.store({
  apiKey: linearKey,
  team: 'PRD',
  workflow: ['Todo', 'In Progress', 'In Review', 'Done', 'Canceled'],
});
const fromIssue = (issue: LinearIssue) => ({
  ref: issue.identifier,
  title: issue.title,
  description: issue.description,
  notes: [],
});

const bugLane = H.lane('bugs', bug)
  .supply(linear.issues({ apiKey: linearKey, team: 'PRD', labels: ['bug'] }), (issue, to) => to.create(fromIssue(issue)))
  .supply(folder.files({ path: 'inbox/bugs', glob: '*.md' }), (file, to) => to.create({
    ref: file.path,
    title: file.name,
    description: file.body,
    notes: [],
  }))
  .supply(H.operator)
  .handler(deliver, { exits: { shipped, dropped, reopened: open }, params: { rounds: 3 } })
  .store(tracker, {
    states: { open: 'Todo', shipped: 'Done', dropped: 'Canceled', abandoned: 'Canceled' },
    inFlight: 'In Progress',
    steps: { review: 'In Review' },
  })
  .retry({ maxAttempts: 2, backoff: 'exponential', initialDelayMs: 60000, exhausted: abandoned })
  .on(H.cancel, { enter: dropped });

const featureLane = H.lane('features', feature)
  .supply(linear.issues({ apiKey: linearKey, team: 'PRD', labels: ['feature'] }), (issue, to) => to.create(fromIssue(issue)))
  .supply(H.operator)
  .handler(deliver, { exits: { shipped, dropped, reopened: open }, params: { rounds: 5 } })
  .store(tracker, {
    states: { open: 'Todo', shipped: 'Done', dropped: 'Canceled', abandoned: 'Canceled' },
    inFlight: 'In Progress',
    steps: { review: 'In Review' },
  })
  .retry({ maxAttempts: 2, backoff: 'exponential', initialDelayMs: 60000, exhausted: abandoned })
  .on(H.cancel, { enter: dropped });

const decompose = H.flow('decompose')
  .input(workSchema)
  .step('plan', planner, ctx => ({
    task: `Decompose the epic ${ctx.unit.attributes.title}:\n${ctx.unit.attributes.description}`,
  }), { afterCrash: 'askDriver' })
  .spawn('features', featureLane, ctx => ctx.steps.plan.features.map((planned, index) => ({
    ref: `${ctx.unit.key}-${index + 1}`,
    title: planned.title,
    description: planned.description,
    notes: [],
  })))
  .exit('completed', ctx => ctx.steps.features.every(child => child.verdict === 'success' || child.verdict === 'neutral'))
  .exit('incomplete');

const epicLane = H.lane('epics', epic)
  .supply(linear.issues({ apiKey: linearKey, team: 'PRD', labels: ['epic'] }), (issue, to) => to.create(fromIssue(issue)))
  .handler(decompose, { exits: { completed: shipped, incomplete: abandoned } })
  .store(tracker, {
    states: { open: 'Todo', shipped: 'Done', dropped: 'Canceled', abandoned: 'Canceled' },
    inFlight: 'In Progress',
  })
  .retry({ maxAttempts: 2, backoff: 'fixed', initialDelayMs: 300000, exhausted: abandoned })
  .on(H.cancel, { enter: dropped });

const probeService = H.command('probe-service')
  .input(z.object({ service: service.schema }))
  .argv(input => ['./scripts/probe.sh', input.service])
  .runner(localRunner);

const heartbeatFlow = H.flow('heartbeat')
  .input(z.object({ service: service.schema }))
  .step('probe', probeService, ctx => ({ service: ctx.unit.attributes.service }), { afterCrash: 'rerun' })
  .exit('healthy');

const heartbeatLane = H.lane('heartbeats', heartbeat)
  .supply(H.clock('every-five-minutes').every({ minutes: 5 }), (tick, to) => service.values.map(name => to.create({ service: name })))
  .handler(heartbeatFlow, { exits: { healthy } })
  .retry({ maxAttempts: 1, exhausted: unhealthy });

const unhealthyServiceFilesBug = H.trigger('unhealthy-service-files-bug')
  .on(H.when.transition(heartbeatLane, { to: unhealthy }))
  .create(bugLane, event => ({
    ref: `heartbeat-${event.unit.attributes.service}-${event.at.toISOString()}`,
    title: `Service ${event.unit.attributes.service} failed its heartbeat`,
    description: `The heartbeat probe for ${event.unit.attributes.service} failed at ${event.at.toISOString()}.`,
    notes: [],
  }));

const experience = H.memory('experience', 'experience');
const taste = H.memory('taste', 'taste');

const experienceJournal = H.journal('coding-experience', experience)
  .store(jsonl.memoryStore({ path: 'memory/experience.jsonl' }))
  .recall({ by: 'specificity', limit: 12 })
  .readBy(builderRole, auditorRole)
  .recordedBy(auditorRole);

const tasteJournal = H.journal('owner-taste', taste)
  .store(jsonl.memoryStore({ path: 'memory/taste.jsonl' }))
  .recall({ by: 'specificity', limit: 20 })
  .readBy(builderRole, plannerRole);

const scheduler = H.scheduler('coding-team')
  .expedite(heartbeatLane)
  .standard(bugLane, featureLane, epicLane)
  .wip(bugLane, 2)
  .wip(epicLane, 1)
  .aging(featureLane, { afterMinutes: 240 });

const productionProbe = H.command('production-health-probe')
  .argv(['./scripts/probe-production.sh'])
  .runner(localRunner);

const supervisor = claudeCode.supervisor('supervisor', {
  grants: [
    H.ops.workRead,
    H.ops.workCreate,
    H.ops.workUpdate,
    H.ops.workMove,
    H.ops.workCancel,
    H.ops.resolve(ownerDecision, ownerReview),
    H.ops.memoryRead,
    H.ops.memoryWrite,
    H.ops.telemetryRead,
    H.ops.accountsRead,
    H.ops.accountsShare,
    H.operation('production-health', productionProbe),
  ],
});

export const codingTeam = H.harness('coding-team')
  .ledger(sqlite.ledger({ path: '.harness/ledger.sqlite' }))
  .lanes(heartbeatLane, bugLane, featureLane, epicLane)
  .journals(experienceJournal, tasteJournal)
  .triggers(unhealthyServiceFilesBug)
  .scheduler(scheduler)
  .clients(supervisor)
  .observers(markdown.board({ path: 'BOARD.md' }), markdown.telemetry({ path: 'TELEMETRY.md' }));

void codingTeam.start();
=== END ===

