const certLane = H.lane('certificates', CertificateRenewal)
  .supply(H.clock('weekly-cert-check').at('03:00', { on: 'mon', tz: 'UTC' }), (_tick, to) =>
    domainSchema.options.map(domain => to.create({ domain })),
