const failedBackupOpensIncident = H.trigger('failed-backup')
  .on(H.when.transition(backupLane, { to: BackupFailed }))
  .create(incidentLane, e => ({
    ref: `backup-${e.unit.attributes.database}-${e.unit.attributes.night}`,
